<?php
header('Content-Type: application/json; charset=utf-8');
require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/db.php'; require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/question_bank_blueprint.php'; requireAuth(); $pdo=getDBConnection();
try{
 $in=json_decode(file_get_contents('php://input'),true)?:[]; $course=strtoupper(trim((string)($in['paper_code']??''))); $sem=trim((string)($in['semester']??'')); $year=trim((string)($in['academic_year']??'')); $exam=trim((string)($in['exam_type']??'')); $qs=$in['questions']??[]; if($course==='')throw new RuntimeException('Course code is required.');
 $st=$pdo->prepare("SELECT * FROM question_bank_blueprints WHERE status='PUBLISHED' AND qbb_enabled=1 AND UPPER(paper_code)=UPPER(?) AND (semester=? OR semester IS NULL OR semester='') AND (academic_year=? OR academic_year IS NULL OR academic_year='') AND (exam_type=? OR exam_type IS NULL OR exam_type='') ORDER BY published_at DESC,id DESC LIMIT 1"); $st->execute([$course,$sem,$year,$exam]); $bp=$st->fetch(PDO::FETCH_ASSOC);
