 $matrix=json_decode((string)$bp['matrix_json'],true);if(!is_array($matrix))$matrix=[]; $sub=[];$unit=[]; foreach($qs as $q){$u=(int)($q['unit_no']??$q['unit']??0);$su=trim((string)($q['sub_unit']??$q['subunit']??($u.'.1')));$unit[$u]=($unit[$u]??0)+1;$sub[$su]=($sub[$su]??0)+1;}
 $reqSub=[];$reqUnit=[];$rows=[];$errors=[]; foreach($matrix as $i=>$r){$u=(int)($r['unit']??0);$su=(string)($r['sub_unit']??'');$need=(int)($r['required_count']??0);$reqSub[$su]=($reqSub[$su]??0)+$need;$reqUnit[$u]=($reqUnit[$u]??0)+$need;$a=(int)($sub[$su]??0);$au=(int)($unit[$u]??0);$rows[]=['row_no'=>$i+1,'unit'=>$u,'sub_unit'=>$su,'section'=>(string)($r['section']??''),'k_level'=>(string)($r['k_level']??''),'co_level'=>'CO'.preg_replace('/\D/','',(string)($r['k_level']??'K1')),'marks'=>(int)($r['marks']??0),'question_type'=>(string)($r['question_type']??''),'required_count'=>$need,'available_subunit'=>$a,'available_unit'=>$au];}
